import hashlib
start=G['current']['start']
def sh(b): return hashlib.md5(str(b).encode()).hexdigest()
print('current hash',sh(start))
for i,t in enumerate(G['all']):
 if sh(t['start'])==sh(start): print('MATCH',i,t)
# summarize solved trajectories and starts via block coords
for i,t in enumerate(G['all']):
 if any(s.get('completed') for s in t['steps']):
  acts=[]
  for s in t['steps']: acts.extend(s.get('actions',[]))
  print('solved',i,len(t['steps']),acts)
